import React, { useState } from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { useNavigate } from "react-router-dom";
function Delusion(){
    const navigate = useNavigate();
    const { ref, inView } = useInView();
    const [isVideoOpen, setIsVideoOpen] = useState(false);
    return(
        <>
          <p
          className="underline text-base sm:text-lg md:text-xl lg:text-l cursor-pointer pl-5"
          onClick={() => navigate(-1)}
          >
          Go Back
              </p>

            {/* Heading Section */}
            <div className="flex flex-col items-center justify-center mt-10">
              <h2 className="text-3xl font-bold text-black text-center">Delusion-A short film</h2>
            </div>

            {/* Video Placeholder with Cover Image */}
            <div className="flex justify-center items-center w-full mt-10 px-4">
              <div
                className="relative w-full max-w-4xl h-[250px] sm:h-[350px] md:h-[450px] lg:h-[500px] bg-cover bg-center cursor-pointer flex items-center justify-center"
                style={{ backgroundImage: "url('/kalpana.avif')" }}
                onClick={() => setIsVideoOpen(true)}
              >

              </div>
              </div>
{/*  */}
              <div className="bg-black flex flex-col items-center justify-center text-white w-full py-20 space-y-4">
                          <div className="flex flex-wrap justify-between w-full max-w-3xl items-start gap-4">
                            <ul className="space-y-1">
                              <li className="text-lg font-semibold">CONTACT</li>
                              <li>
                                <a
                                  href="mailto:sanskritichauhan1234@gmail.com"
                                  className="hover:underline"
                                >
                                  sanskritichauhan1234@gmail.com
                                </a>
                              </li>
                              <li>
                                <a href="tel:+919867067656" className="hover:underline">
                                  +91 9867067656
                                </a>
                              </li>
                            </ul>
                            <nav>
                              <ul className="flex flex-col items-center space-y-1">
                                <Link to="/" className="text-lg hover:underline">
                                  HOME
                                </Link>
                                <Link to="/about" className="text-lg hover:underline">
                                  ABOUT
                                </Link>
                                <Link to="/portfolio" className="text-lg hover:underline">
                                  PORTFOLIO
                                </Link>
                                <Link to="/photography" className="text-lg hover:underline">
                                  PHOTOGRAPHY
                                </Link>
                              </ul>
                            </nav>
                          </div>

                          {/* Name Display - Animated */}
                          <motion.div
                            ref={ref}
                            className="text-center"
                            initial={{ opacity: 0, y: 50 }}
                            animate={inView ? { opacity: 1, y: 0 } : {}}
                            transition={{ duration: 0.8, ease: "easeOut" }}
                          >
                            <span className="font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">
                              SANSKRITI CHAUHAN
                            </span>
                          </motion.div>
                        </div>

    </>
    )
};

export default Delusion;
